SELECT m.TRADEDATE AS `交易日期`, m.STOCKSNAME AS `股票名称`, m.SECCODE AS `股票代码`, ROUND(m.TOPEN,2) AS `开盘价`, ROUND(m.TCLOSE,2) AS `收盘价`, ROUND(m.THIGH,2) AS `最高价`, ROUND(m.TLOW,2) AS `最低价`, ROUND(m.TVALUE/100000000,2) AS `成交额(亿)`, ROUND(m.TVOLUME/100000000,2) AS `成交量(亿股)`, ROUND(m.CHNG,2) AS `涨跌额`, ROUND(m.CHNG_PCT,2) AS `涨跌幅(%)` FROM STK_MKT m INNER JOIN GET_A_SEC_CODE c ON m.INNER_CODE = c.INNER_CODE WHERE m.STOCKSNAME LIKE '%兴业银行%' AND m.TRADEDATE = '2026-08-31' AND m.ISVALID = 1 AND c.ISVALID = 1 AND m.TCLOSE IS NOT NULL LIMIT 1;
